/* ============================================================
   Tikabhairab Rajkulo — platform app logic.
   Depends on Leaflet 1.9, data.js (CANAL_SECTIONS, CANAL_POIS,
   CANAL_HISTORIC) and i18n.js (I18N) loaded beforehand.
   ============================================================ */

// ── PHOTO CONFIGURATION ─────────────────────────────────────
// thumbs/ = 400 px gallery images; large/ = 800 px images for the lightbox.
// Both are generated by scripts/build_thumbnails.py.
const PHOTO_THUMB_BASE = 'photos/thumbs/';
const PHOTO_FULL_BASE  = 'photos/large/';

// ── STATE ───────────────────────────────────────────────────
let map, satelliteLayer, streetLayer;
let historicLayer, labelsLayer;
let sectionLayers = [];        // [{line, section, bucket}]
let poiMarkers   = [];         // [{marker, poi}]
let activeSection = null;
let currentDetail = null;      // {kind: 'section' | 'poi', item}
let tour = { active: false, idx: 0 };
let indexSortKey = 'pdf_n';
let indexSortAsc = true;

const CONDITIONS = ['Good', 'Fair', 'Poor', 'Critical', 'Underground', 'Lost', 'No data'];
const CONDITION_COLORS = {
  Good: '#1D9E75', Fair: '#d4a017', Poor: '#d4721a', Critical: '#c0392b',
  Underground: '#7c4a1e', Lost: '#333333', 'No data': '#9aa0a6',
};

const filterState = {
  flow:     new Set(['Perennial', 'Seasonal', 'Other']),
  features: new Set(['surveyed', 'pois', 'labels']),
  poiCats:  new Set(['Contamination','Cross Drainage','Vulnerable Zone',
                     'Encroachment','Hume Pipe','Intake Structure','Observation Point']),
  conditions: new Set(CONDITIONS),
};

// Observation points are numerous and low-priority: draw them as small dots so they
// don't hide the condition-coloured canal line underneath.
const MINOR_POI_CATS = new Set(['Observation Point']);

const POI_COLORS = {
  'Contamination':    '#c0392b',
  'Cross Drainage':   '#2a6b8a',
  'Vulnerable Zone':  '#d4721a',
  'Encroachment':     '#333333',
  'Hume Pipe':        '#7c4a1e',
  'Intake Structure': '#1D9E75',
  'Observation Point':'#2a6b8a',
};

const MAP_STYLES = {
  historic: { color: '#f97316', weight: 3, opacity: 0.95, smoothFactor: 1 },
  surveyed: { weight: 5, opacity: 0.92, smoothFactor: 1 },
};

const SETTLEMENTS = [
  { key: 'place.intake',    lat: 27.5741, lon: 85.3179 },
  { key: 'place.chapagaon', lat: 27.5900, lon: 85.3150 },
  { key: 'place.pyangaon',  lat: 27.6050, lon: 85.3170 },
  { key: 'place.thecho',    lat: 27.6200, lon: 85.3190 },
  { key: 'place.sunakothi', lat: 27.6380, lon: 85.3210 },
  { key: 'place.dholahiti', lat: 27.6520, lon: 85.3230 },
  { key: 'place.end',       lat: 27.6650, lon: 85.3183 },
];

// ── LANGUAGE ────────────────────────────────────────────────
let LANG = initialLang();

function initialLang() {
  const q = new URLSearchParams(location.search).get('lang');
  if (q === 'en' || q === 'ne') return q;
  try {
    const saved = localStorage.getItem('rajkulo-lang');
    if (saved === 'en' || saved === 'ne') return saved;
  } catch (e) { /* storage unavailable */ }
  return /^ne\b/i.test(navigator.language || '') ? 'ne' : 'en';
}

// Look up a string and fill its {placeholders}.
function t(key, params) {
  let s = (I18N[LANG] && I18N[LANG][key] != null) ? I18N[LANG][key]
        : (I18N.en[key] != null ? I18N.en[key] : key);
  if (params) s = s.replace(/\{(\w+)\}/g, (m, k) => (params[k] != null ? params[k] : m));
  return s;
}
// Translate a recorded data value (condition, flow, water quality…) when a label exists.
function tv(prefix, value) {
  if (value == null || value === '' || value === '—') return '—';
  const key = prefix + value;
  return (I18N.en[key] != null) ? t(key) : value;
}

const DEVANAGARI_DIGITS = '०१२३४५६७८९';
function digits(str) {
  return LANG === 'ne' ? String(str).replace(/[0-9]/g, d => DEVANAGARI_DIGITS[d]) : String(str);
}
// Number → localised string with grouping, e.g. 3,124 or ३,१२४.
function N(x, decimals = 0) {
  if (x == null || isNaN(x)) return '—';
  return digits(Number(x).toLocaleString('en-US', { minimumFractionDigits: decimals, maximumFractionDigits: decimals }));
}
const km = (m, d = 1) => N(m / 1000, d);
// Chainage → station notation "3+124 m".
function formatStation(m, withUnit = true) {
  if (m == null) return '—';
  const r = Math.round(m);
  const s = `${Math.floor(r / 1000)}+${String(r % 1000).padStart(3, '0')}`;
  return digits(s) + (withUnit ? ` ${t('unit.m')}` : '');
}
function stationRange(a, b) {
  return `${formatStation(a, false)}–${formatStation(b, false)} ${t('unit.m')}`;
}

function setLang(lang) {
  LANG = lang;
  try { localStorage.setItem('rajkulo-lang', lang); } catch (e) { /* ignore */ }
  const url = new URL(location.href);
  if (lang === 'en') url.searchParams.delete('lang'); else url.searchParams.set('lang', lang);
  history.replaceState(null, '', url);
  applyLanguage();
}

// Re-render everything that shows text.
function applyLanguage() {
  applyStaticText();
  populateCounts();
  renderFindings();
  renderStudy();
  renderConditionStrip();
  if (!map) return;
  buildLegendCounts();
  sectionLayers.forEach(({ line, section }) => line.setTooltipContent(sectionTooltipHTML(section)));
  poiMarkers.forEach(({ marker, poi }) => marker.setTooltipContent(poiTooltipHTML(poi)));
  const labelsOn = labelsLayer && map.hasLayer(labelsLayer);
  if (labelsLayer) map.removeLayer(labelsLayer);
  buildLabels();
  if (labelsOn) labelsLayer.addTo(map);
  updateFilterStats();
  renderIndex();
  if (currentDetail) {
    if (currentDetail.kind === 'section') renderSectionDetail(currentDetail.item);
    else renderPOIDetail(currentDetail.item);
  }
  if (tour.active) renderTourStop({ fly: false });
}

// Fill every element marked up with data-i18n / data-i18n-html / data-i18n-attr.
function applyStaticText() {
  const P = statParams();
  document.documentElement.lang = LANG;
  document.body.classList.toggle('lang-ne', LANG === 'ne');
  document.title = t('doc.title');
  document.querySelectorAll('[data-i18n]').forEach(el => { el.textContent = t(el.dataset.i18n, P); });
  document.querySelectorAll('[data-i18n-html]').forEach(el => { el.innerHTML = t(el.dataset.i18nHtml, P); });
  document.querySelectorAll('[data-i18n-attr]').forEach(el => {
    el.dataset.i18nAttr.split(',').forEach(pair => {
      const [attr, key] = pair.split('=').map(x => x.trim());
      if (attr && key) el.setAttribute(attr, t(key, P));
    });
  });
  document.querySelectorAll('[data-n]').forEach(el => {
    el.textContent = N(+el.dataset.n) + (el.dataset.unit ? ` ${t('unit.' + el.dataset.unit)}` : '');
  });
  document.querySelectorAll('[data-cond-label]').forEach(el => {
    const c = el.dataset.condLabel;
    el.textContent = `${t('cond.' + c)} — ${t('condDesc.' + c)}`;
  });
  if (tour.active === false) document.getElementById('tour-next').textContent = t('tour.next');
  renderDownloadSizes();
}

// ── SMALL HELPERS ───────────────────────────────────────────
const isPlaceholder = s => !!s.is_connector;
const wqList = s => (Array.isArray(s.wq_list) && s.wq_list.length) ? s.wq_list
  : (s.wq && s.wq !== '—' ? [s.wq] : []);
const hasSewage = s => wqList(s).some(w => /sewage|waste/i.test(w));
const isMobile = () => window.innerWidth <= 768;

// Chainage in the survey workbook is the running distance at the END of a section
// (Chainage = previous chainage + this section's length).
function chainageStart(s) {
  return (s.chainage != null && s.sec_len != null) ? s.chainage - s.sec_len : null;
}
function wqColor(w) {
  const k = (w || '').toLowerCase();
  if (/sewage|waste/.test(k)) return '#c0392b';
  if (/storm|irrigation/.test(k)) return '#2f7fa8';
  if (/mixed/.test(k)) return '#b8860b';
  if (/river|drinking/.test(k)) return '#1D9E75';
  return '#6b7280';
}
function sectionLabel(s) {
  const ref = t('detail.section', { n: digits(s.pdf_n) });
  return (s.tole && s.tole !== '—') ? `${ref} · ${s.tole}` : ref;
}
function cmValue(v) {
  const n = parseFloat(v);
  return isNaN(n) ? '—' : N(n, Number.isInteger(n) ? 0 : 1);
}

function flowBucket(flow) {
  const f = (flow || '').toString().trim();
  if (!f || f === '—') return 'Other';
  if (/^perennial$/i.test(f)) return 'Perennial';
  if (/seasonal|intermittent/i.test(f)) return 'Seasonal';
  return 'Other';
}

function matchesFilters(section, bucket) {
  const flowMatches = filterState.flow.size === 0 || filterState.flow.has(bucket);
  const conditionMatches = filterState.conditions.size === 0 || filterState.conditions.has(section.condition);
  return flowMatches && conditionMatches;
}

function debounce(fn, delay) {
  let timeoutId;
  return function(...args) {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => fn(...args), delay);
  };
}

// ── FACTS FROM THE DATA ─────────────────────────────────────
// Every number quoted in the findings and the tour is computed here from data.js,
// so the text can never drift out of step with the survey data.
const STATS = computeStats();

function haversine(a, b) {
  const R = 6371000, rad = d => d * Math.PI / 180;
  const dLat = rad(b[1] - a[1]), dLon = rad(b[0] - a[0]);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a[1])) * Math.cos(rad(b[1])) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}
// Chainage of a point: nearest vertex of a GPS-walked section, measured along that section.
function chainageOfPoint(lon, lat) {
  let best = null;
  CANAL_SECTIONS.forEach(s => {
    if (isPlaceholder(s) || !s.coords || s.coords.length < 2 || s.chainage == null) return;
    const total = s.coords.reduce((acc, p, i) => i ? acc + haversine(s.coords[i - 1], p) : 0, 0);
    let along = 0;
    s.coords.forEach((p, i) => {
      if (i) along += haversine(s.coords[i - 1], p);
      const d = haversine(p, [lon, lat]);
      if (!best || d < best.d) best = { d, ch: chainageStart(s) + (total ? along / total * s.sec_len : 0) };
    });
  });
  return best ? best.ch : null;
}

function computeStats() {
  const S = CANAL_SECTIONS, sum = a => a.reduce((x, s) => x + (s.sec_len || 0), 0);
  const median = a => { const b = a.slice().sort((p, q) => p - q); return b.length ? b[Math.floor(b.length / 2)] : null; };
  const st = {};
  st.sections = S.length;
  st.gps = S.filter(s => !isPlaceholder(s)).length;
  st.pois = CANAL_POIS.length;
  st.historic = typeof CANAL_HISTORIC !== 'undefined' ? CANAL_HISTORIC.length : 0;
  st.photos = new Set([...S.flatMap(s => s.photos || []), ...CANAL_POIS.flatMap(p => p.photos || [])]).size;
  const days = [...new Set(S.filter(s => s.created).map(s => s.created.slice(0, 10)))].sort();
  st.days = days.length;
  st.dayFrom = days.length ? +days[0].slice(8, 10) : null;
  st.dayTo = days.length ? +days[days.length - 1].slice(8, 10) : null;
  st.mainM = Math.max(...S.filter(s => s.chainage != null).map(s => s.chainage));

  // Flow
  const per = S.filter(s => s.flow === 'Perennial');
  const lastPer = per.reduce((a, s) => (!a || s.chainage > a.chainage ? s : a), null);
  st.perEndM = lastPer ? lastPer.chainage : null;
  st.perLast = lastPer ? lastPer.pdf_n : null;
  const seas = S.filter(s => s.flow === 'Seasonal' && s.chainage != null);
  st.seasStartM = seas.length ? Math.min(...seas.map(chainageStart)) : null;

  // Water quality
  const sew = S.filter(hasSewage);
  st.sewN = sew.length;
  st.sewM = sum(sew);
  const firstSew = sew.slice().sort((a, b) => chainageStart(a) - chainageStart(b))[0];
  st.firstSew = firstSew || null;
  const withWq = S.filter(s => wqList(s).length && s.chainage != null);
  const up = withWq.filter(s => s.chainage <= st.perEndM);
  const down = withWq.filter(s => chainageStart(s) >= st.seasStartM);
  st.upWq = up.length; st.upSew = up.filter(hasSewage).length;
  st.downWq = down.length; st.downSew = down.filter(hasSewage).length;

  // Contamination points of interest, in order along the canal
  st.contam = CANAL_POIS.filter(p => p.cat === 'Contamination')
    .map(p => ({ poi: p, ch: chainageOfPoint(p.lon, p.lat) }))
    .sort((a, b) => a.ch - b.ch);

  // Silting, lining, dimensions
  st.silt = S.filter(s => s.silting === 'Present').length;
  st.siltRec = S.filter(s => s.silting === 'Present' || s.silting === 'Absent').length;
  st.lined = S.filter(s => s.lined === 'Yes').length;
  st.linedRec = S.filter(s => s.lined === 'Yes' || s.lined === 'No').length;
  st.oneSide = S.filter(s => /one[\s-]?sided?|on sided/i.test(s.notes || '')).length;
  const rect = S.filter(s => s.shape === 'Rectangular');
  st.medW = median(rect.map(s => parseFloat(s.width)).filter(v => !isNaN(v)));
  st.medH = median(rect.map(s => parseFloat(s.height)).filter(v => !isNaN(v)));

  // Lost from view, pipes, underground notes
  const lost = S.filter(s => s.condition === 'Lost');
  st.lostN = lost.length; st.lostM = sum(lost);
  const lostMid = lost.filter(s => chainageStart(s) >= st.perEndM);
  st.lostMidN = lostMid.length; st.lostMidM = sum(lostMid);
  st.lostFromM = lostMid.length ? Math.min(...lostMid.map(chainageStart)) : null;
  st.lostToM = lostMid.length ? Math.max(...lostMid.map(s => s.chainage)) : null;
  const pipes = S.filter(s => s.shape === 'Circular');
  const diams = pipes.map(s => parseFloat(s.diam)).filter(v => !isNaN(v));
  st.pipeN = pipes.length;
  st.pipeMin = diams.length ? Math.min(...diams) : null;
  st.pipeMax = diams.length ? Math.max(...diams) : null;
  st.ugNotes = S.filter(s => /underground|under ground|below road|under road/i.test(s.notes || '')).length;

  // Last section with any field observation
  const observed = S.filter(s => !isPlaceholder(s) && s.condition !== 'No data' && s.chainage != null);
  st.lastObsM = observed.length ? Math.max(...observed.map(s => s.chainage)) : null;
  return st;
}

// Formatted values for the {placeholders} in the current language.
function statParams() {
  const s = STATS, first = s.contam[0];
  return {
    sections: N(s.sections), gps: N(s.gps), pois: N(s.pois), photos: N(s.photos), hist: N(s.historic),
    days: N(s.days), from: N(s.dayFrom), to: N(s.dayTo), mainKm: km(s.mainM),
    perM: N(Math.round(s.perEndM)), perEnd: formatStation(s.perEndM), perLast: N(s.perLast),
    seasStart: formatStation(s.seasStartM),
    poiFid: first ? N(first.poi.fid) : '—',
    poiComment: first ? escapeHTML((first.poi.comment || '').trim()) : '—',
    poiSt: first ? formatStation(first.ch) : '—',
    firstSew: s.firstSew ? N(s.firstSew.pdf_n) : '—',
    firstSewSt: s.firstSew ? stationRange(chainageStart(s.firstSew), s.firstSew.chainage) : '—',
    sewN: N(s.sewN), sewKm: km(s.sewM, 2),
    upSew: N(s.upSew), upWq: N(s.upWq), downSew: N(s.downSew), downWq: N(s.downWq),
    nContam: N(s.contam.length),
    list: s.contam.map(c => t('f.pointItem', { st: formatStation(c.ch), c: escapeHTML((c.poi.comment || '').trim()) })).join(', '),
    silt: N(s.silt), siltRec: N(s.siltRec), siltPct: N(100 * s.silt / Math.max(s.siltRec, 1)),
    lined: N(s.lined), linedRec: N(s.linedRec), oneSide: N(s.oneSide), medW: N(s.medW), medH: N(s.medH),
    lostN: N(s.lostN), lostKm: km(s.lostM, 2), lostMidN: N(s.lostMidN), lostMidKm: km(s.lostMidM, 2),
    lostFrom: km(s.lostFromM), lostTo: km(s.lostToM),
    pipeN: N(s.pipeN), pipeMin: N(s.pipeMin), pipeMax: N(s.pipeMax), ugNotes: N(s.ugNotes),
    lastObsSt: formatStation(s.lastObsM),
  };
}

// ── INIT ────────────────────────────────────────────────────
window.addEventListener('DOMContentLoaded', () => {
  applyStaticText();
  populateCounts();
  renderFindings();
  renderStudy();
  renderConditionStrip();
  fillDownloadSizes();
  bindStudy();
  bindLanguageToggle();
  bindSplash();
  bindKeyboard();
  bindAccordions();
  bindDownloadLinks();

  // Auto-enter if URL has a deep link
  const hash = parseHash();
  if (hash.section != null || hash.poi != null || hash.tour === '1') {
    enterApp(false);
  }
});

// Back/forward buttons and links pasted into an open tab.
window.addEventListener('hashchange', () => { if (map) applyHashOnLoad(); });

function bindLanguageToggle() {
  document.querySelectorAll('[data-lang-toggle]').forEach(b => {
    b.addEventListener('click', () => setLang(LANG === 'ne' ? 'en' : 'ne'));
  });
}

// Fill every count in the page from the data.
function populateCounts() {
  const setAll = (sel, val) => document.querySelectorAll(sel).forEach(el => { el.textContent = val; });
  setAll('[data-stat="sections"]', N(STATS.sections));
  setAll('[data-stat="gps-sections"]', N(STATS.gps));
  setAll('[data-stat="pois"]', N(STATS.pois));
  setAll('[data-stat="historic"]', N(STATS.historic));

  const flow = { Perennial: 0, Seasonal: 0, Other: 0 };
  CANAL_SECTIONS.forEach(s => { flow[flowBucket(s.flow)]++; });
  document.querySelectorAll('[data-flow-count]').forEach(el => { el.textContent = N(flow[el.dataset.flowCount] || 0); });

  const poi = {};
  CANAL_POIS.forEach(p => { poi[p.cat] = (poi[p.cat] || 0) + 1; });
  document.querySelectorAll('[data-poi-count]').forEach(el => {
    const n = poi[el.dataset.poiCount] || 0;
    el.textContent = N(n);
    el.closest('label').hidden = n === 0;
  });
}

function bindSplash() {
  const enterBtn = document.getElementById('btn-enter');
  const tourBtn  = document.getElementById('btn-tour');
  if (enterBtn) enterBtn.addEventListener('click', () => enterApp(false));
  if (tourBtn)  tourBtn .addEventListener('click', () => enterApp(true));
}

function enterApp(startTour) {
  const splash = document.getElementById('splash');
  if (splash) {
    splash.classList.add('hiding');
    setTimeout(() => splash.style.display = 'none', 600);
  }
  document.getElementById('app').classList.add('visible');
  setTimeout(() => {
    initMap();
    if (startTour) startTourMode();
    applyHashOnLoad();
  }, 300);
}

// ── MAP & LAYERS ────────────────────────────────────────────
function initMap() {
  map = L.map('map', {
    zoomControl: true,
    attributionControl: true,
    keyboard: true,
  }).setView([27.6197, 85.3183], 13);

  satelliteLayer = L.tileLayer(
    'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
    { attribution: 'Esri World Imagery', maxZoom: 19 }
  ).addTo(map);
  streetLayer = L.tileLayer(
    'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
    { attribution: '© OpenStreetMap', maxZoom: 19 }
  );

  // Panes give us explicit z-order. Surveyed lines always above historic branches.
  map.createPane('historicPane').style.zIndex = 350;
  map.createPane('surveyedPane').style.zIndex = 420;

  buildLayers();
  buildLegendCounts();
  buildIndex();
  bindNavTabs();
  bindFilterChips();
  bindFilterEvents();
  bindMapControls();
  bindSearch();
  bindTourControls();
  bindMobileSheet();

  applyFilters({ fit: true });
}

function buildLayers() {
  if (typeof CANAL_HISTORIC !== 'undefined') {
    const histLines = CANAL_HISTORIC.map(h => L.polyline(
      h.coords.map(c => [c[1], c[0]]),
      { ...MAP_STYLES.historic, pane: 'historicPane' }
    ).bindTooltip(
      `<strong>${escapeHTML(t('feat.historic'))} · ${escapeHTML(h.id || '—')}</strong>`,
      { sticky: true, offset: [10, 0] }
    ));
    historicLayer = L.layerGroup(histLines);
  }

  sectionLayers = [];
  CANAL_SECTIONS.forEach(s => {
    if (!s.coords || s.coords.length < 2) return;
    const latlngs = s.coords.map(c => [c[1], c[0]]);
    const line = L.polyline(latlngs, {
      ...MAP_STYLES.surveyed, color: s.color, pane: 'surveyedPane',
      dashArray: isPlaceholder(s) ? '6 8' : null,   // approximate geometry → dashed
    });
    line.bindTooltip(sectionTooltipHTML(s), { sticky: true, offset: [10, 0] });
    line.on('click', () => selectSection(s));
    line.on('mouseover', function () { this.setStyle({ weight: 8, opacity: 1 }); });
    line.on('mouseout',  function () { if (activeSection !== s) this.setStyle({ weight: 5, opacity: 0.92 }); });
    sectionLayers.push({ line, section: s, bucket: flowBucket(s.flow) });
  });

  poiMarkers = [];
  CANAL_POIS.forEach(poi => {
    const col = POI_COLORS[poi.cat] || '#2a6b8a';
    const minor = MINOR_POI_CATS.has(poi.cat);
    const size = minor ? 12 : 26;
    const icon = L.divIcon({
      html: minor
        ? `<div class="poi-dot" style="background:${col}" aria-hidden="true"></div>`
        : `<div class="poi-pin" style="background:${col}" aria-hidden="true">${poi.icon}</div>`,
      className: '', iconSize: [size, size], iconAnchor: [size / 2, size / 2],
    });
    const marker = L.marker([poi.lat, poi.lon], { icon, keyboard: true,
      alt: `${poi.cat}: ${poi.comment || ''}`, title: `${poi.cat} #${poi.fid}` });
    marker.bindTooltip(poiTooltipHTML(poi), { offset: [10, 0] });
    marker.on('click', () => selectPOI(poi));
    poiMarkers.push({ marker, poi });
  });

  buildLabels();
}

function buildLabels() {
  const labels = SETTLEMENTS.map(s => {
    const icon = L.divIcon({
      html: `<div class="settlement-label">${escapeHTML(t(s.key))}</div>`,
      className: '', iconSize: undefined,
    });
    return L.marker([s.lat, s.lon], { icon, interactive: false });
  });
  labelsLayer = L.layerGroup(labels);
}

function sectionTooltipHTML(s) {
  const len = s.sec_len != null ? `${N(s.sec_len, 1)} ${t('unit.m')}  ·  ` : '';
  const meta = s.mergin_fid != null
    ? `<span class="tt-meta">${escapeHTML(t('detail.mergin', { n: s.mergin_fid }))}</span>`
    : `<span class="tt-meta">${escapeHTML(t('tip.approx'))}</span>`;
  const wq = wqList(s).map(w => tv('wq.', w)).join(' + ') || '—';
  return `<strong>${escapeHTML(sectionLabel(s))}</strong>${escapeHTML(t('cond.' + s.condition))} · ${escapeHTML(tv('flow.', s.flow))}<br>${len}${escapeHTML(t('tip.wq'))}: ${escapeHTML(wq)}${meta}`;
}
function poiTooltipHTML(poi) {
  return `<strong>${escapeHTML(tv('poi.', poi.cat))} · #${digits(poi.fid)}</strong>${escapeHTML(poi.comment || '')}`;
}

// ── FILTERS ─────────────────────────────────────────────────
function buildLegendCounts() {
  const counts = Object.fromEntries(CONDITIONS.map(c => [c, 0]));
  CANAL_SECTIONS.forEach(s => {
    if (s.coords && s.coords.length >= 2 && counts[s.condition] != null) counts[s.condition]++;
  });
  document.querySelectorAll('[data-cond-count]').forEach(el => {
    const c = el.dataset.condCount;
    if (counts[c] == null) return;
    el.textContent = N(counts[c]);
    el.closest('[data-cond-chip]').hidden = counts[c] === 0;   // no empty legend entries
  });
}

function bindFilterChips() {
  document.querySelectorAll('[data-cond-chip]').forEach(chip => {
    const toggle = () => {
      const cond = chip.dataset.condChip;
      if (filterState.conditions.has(cond)) filterState.conditions.delete(cond);
      else filterState.conditions.add(cond);
      chip.classList.toggle('off', !filterState.conditions.has(cond));
      chip.setAttribute('aria-pressed', filterState.conditions.has(cond));
      applyFilters();
    };
    chip.addEventListener('click', toggle);
    chip.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggle(); } });
  });
}

function bindFilterEvents() {
  const updateFilters = () => {
    filterState.flow     = new Set(Array.from(document.querySelectorAll('.flt-flow:checked')).map(e => e.value));
    filterState.features = new Set(Array.from(document.querySelectorAll('.flt-feature:checked')).map(e => e.value));
    filterState.poiCats  = new Set(Array.from(document.querySelectorAll('.flt-poi:checked')).map(e => e.value));
    applyFilters();
  };
  const debouncedUpdate = debounce(updateFilters, 150);
  document.querySelectorAll('.flt-flow, .flt-feature, .flt-poi').forEach(el => {
    el.addEventListener('change', debouncedUpdate);
  });
  const btnReset = document.getElementById('btn-reset');
  const btnFit   = document.getElementById('btn-fit');
  if (btnReset) btnReset.addEventListener('click', resetFilters);
  if (btnFit)   btnFit  .addEventListener('click', fitToVisible);
}

let shownCounts = { sec: 0, poi: 0 };
function applyFilters({ fit = false } = {}) {
  // Add historic FIRST so it sits below surveyed in the SVG render order.
  if (historicLayer) {
    if (filterState.features.has('historic')) {
      historicLayer.addTo(map);
      historicLayer.eachLayer(l => l.bringToBack());
    } else {
      map.removeLayer(historicLayer);
    }
  }

  let shownSec = 0;
  sectionLayers.forEach(({ line, section, bucket }) => {
    const show = filterState.features.has('surveyed') && matchesFilters(section, bucket);
    if (show) { line.addTo(map); line.bringToFront(); shownSec++; }
    else map.removeLayer(line);
  });

  let shownPoi = 0;
  poiMarkers.forEach(({ marker, poi }) => {
    if (filterState.features.has('pois') && filterState.poiCats.has(poi.cat)) { marker.addTo(map); shownPoi++; }
    else map.removeLayer(marker);
  });

  if (labelsLayer) {
    filterState.features.has('labels') ? labelsLayer.addTo(map) : map.removeLayer(labelsLayer);
  }

  shownCounts = { sec: shownSec, poi: shownPoi };
  updateFilterStats();
  if (fit) fitToAll();
}
function updateFilterStats() {
  const stats = document.getElementById('filter-stats');
  if (stats) stats.textContent = t('filters.stats', {
    a: N(shownCounts.sec), b: N(sectionLayers.length), c: N(shownCounts.poi), d: N(poiMarkers.length),
  });
}

function resetFilters() {
  document.querySelectorAll('.flt-flow').forEach(e => e.checked = true);
  document.querySelectorAll('.flt-feature').forEach(e => e.checked = (e.value !== 'historic'));
  document.querySelectorAll('.flt-poi').forEach(e => e.checked = true);
  filterState.conditions = new Set(CONDITIONS);
  document.querySelectorAll('[data-cond-chip]').forEach(c => {
    c.classList.remove('off');
    c.setAttribute('aria-pressed', 'true');
  });
  filterState.flow     = new Set(Array.from(document.querySelectorAll('.flt-flow:checked')).map(e => e.value));
  filterState.features = new Set(Array.from(document.querySelectorAll('.flt-feature:checked')).map(e => e.value));
  filterState.poiCats  = new Set(Array.from(document.querySelectorAll('.flt-poi:checked')).map(e => e.value));
  applyFilters({ fit: true });
}

function fitToVisible() {
  const bounds = L.latLngBounds([]);
  sectionLayers.forEach(({ line, section, bucket }) => {
    if (filterState.features.has('surveyed') && matchesFilters(section, bucket)) {
      line.getLatLngs().forEach(ll => bounds.extend(ll));
    }
  });
  if (filterState.features.has('pois')) {
    poiMarkers.forEach(({ marker, poi }) => {
      if (filterState.poiCats.has(poi.cat)) bounds.extend(marker.getLatLng());
    });
  }
  if (bounds.isValid()) map.fitBounds(bounds.pad(0.08));
}

function fitToAll() {
  const coords = CANAL_SECTIONS.flatMap(s => (s.coords || []).map(c => [c[1], c[0]]));
  if (coords.length) map.fitBounds(L.latLngBounds(coords).pad(0.05));
}

// ── MAP CONTROLS ────────────────────────────────────────────
function bindMapControls() {
  document.querySelectorAll('[data-basemap]').forEach(btn => {
    btn.addEventListener('click', () => switchBasemap(btn.dataset.basemap, btn));
  });
}
function switchBasemap(type, btn) {
  document.querySelectorAll('.map-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  if (type === 'satellite') {
    map.removeLayer(streetLayer); satelliteLayer.addTo(map);
  } else {
    map.removeLayer(satelliteLayer); streetLayer.addTo(map);
  }
}

// ── SECTION / POI SELECTION ─────────────────────────────────
function selectSection(s, opts = {}) {
  activeSection = s;
  currentDetail = { kind: 'section', item: s };
  renderSectionDetail(s);
  showTab('detail');
  expandMobileSheet();
  if (s.coords && s.coords.length) {
    const mid = s.coords[Math.floor(s.coords.length / 2)];
    map.flyTo([mid[1], mid[0]], Math.max(map.getZoom(), 16), { duration: 0.6 });
  }
  sectionLayers.forEach(({ line, section }) => {
    line.setStyle({ weight: section === s ? 8 : 5, opacity: section === s ? 1 : 0.7 });
  });
  if (!opts.skipHash) setHash({ section: s.pdf_n });
}

function selectPOI(poi, opts = {}) {
  currentDetail = { kind: 'poi', item: poi };
  renderPOIDetail(poi);
  showTab('detail');
  expandMobileSheet();
  map.flyTo([poi.lat, poi.lon], Math.max(map.getZoom(), 17), { duration: 0.5 });
  if (!opts.skipHash) setHash({ poi: poi.fid });
}

// ── DETAIL RENDERING ────────────────────────────────────────
function renderSectionDetail(s) {
  const title = sectionLabel(s);

  const photosHTML = (s.photos && s.photos.length)
    ? s.photos.map((p, i) => photoThumbHTML(p, t('detail.photo', { title, i: digits(i + 1) }))).join('')
    : `<div class="no-notes">${escapeHTML(t('detail.noPhotos'))}</div>`;

  const cm = t('unit.cm');
  const dimStr = s.shape === 'Circular' ? `Ø ${cmValue(s.diam)} ${cm}`
    : s.shape === '—' ? '—'
    : `${cmValue(s.width)} ${cm} × ${cmValue(s.height)} ${cm}`;

  // Station Point follows the survey workbook: chainage at the end of the section.
  const stationPoint = formatStation(s.chainage);
  const startM = chainageStart(s);
  const chainStr    = startM     != null ? `${N(startM, 1)} ${t('unit.m')}` : '—';
  const chainEndStr = s.chainage != null ? `${N(s.chainage, 1)} ${t('unit.m')}` : '—';
  const elevStr  = s.zcoord   != null ? `≈ ${N(Math.round(s.zcoord))} ${t('unit.asl')}` : '—';
  const lenStr   = s.sec_len  != null ? `${N(s.sec_len, 2)} ${t('unit.m')}` : '—';
  const merginStr = s.mergin_fid != null ? ` · ${t('detail.mergin', { n: s.mergin_fid })}` : '';

  const wqs = wqList(s);
  const wqHTML = wqs.length
    ? wqs.map(w => `<span class="wq-badge" style="background:${wqColor(w)}"><span class="wq-dot"></span>${escapeHTML(tv('wq.', w))}</span>`).join(' ')
    : '—';

  const placeholder = isPlaceholder(s)
    ? `<div class="placeholder-banner">${escapeHTML(t('detail.placeholder'))}</div>` : '';

  const withGeom = CANAL_SECTIONS.filter(x => x.coords && x.coords.length >= 2);
  const i = withGeom.indexOf(s);
  const prev = i > 0 ? withGeom[i - 1] : null;
  const next = i >= 0 && i < withGeom.length - 1 ? withGeom[i + 1] : null;
  const navHTML = `
    <nav class="detail-nav" aria-label="${escapeHTML(t('detail.navAria'))}">
      <button class="btn" ${prev ? `data-go-section="${prev.pdf_n}"` : 'disabled'} aria-label="${escapeHTML(t('detail.prevAria'))}">${escapeHTML(t('detail.prev'))}</button>
      <button class="btn" ${next ? `data-go-section="${next.pdf_n}"` : 'disabled'} aria-label="${escapeHTML(t('detail.nextAria'))}">${escapeHTML(t('detail.next'))}</button>
    </nav>`;

  const condText = s.condition === 'No data' ? t('cond.No data') : t('detail.condition', { c: t('cond.' + s.condition) });
  const siltColor = s.silting === 'Present' ? '#c0392b' : s.silting === 'Absent' ? '#1D9E75' : '#888';
  const item = (label, value, extra = '') => `<div class="dg-item"${extra}><div class="dg-label">${escapeHTML(label)}</div><div class="dg-val">${value}</div></div>`;
  const notesLang = t('detail.notesLang');

  document.getElementById('detail-content').innerHTML = `
    <button class="detail-back" type="button" data-go-tab="map">${escapeHTML(t('detail.back'))}</button>
    ${navHTML}
    <header class="detail-hero">
      <h2 class="detail-tole">${escapeHTML(title)}</h2>
      <div class="detail-meta">${escapeHTML(t('detail.station'))} ${stationPoint}${escapeHTML(merginStr)}</div>
      <span class="detail-condition" style="background:${s.color}">${escapeHTML(condText)}</span>
    </header>
    ${placeholder}
    <div class="dg-grid">
      ${item(t('detail.station'), stationPoint)}
      ${item(t('detail.length'), lenStr)}
      ${item(t('detail.start'), chainStr)}
      ${item(t('detail.end'), chainEndStr)}
      <div class="dg-item"><div class="dg-label">${escapeHTML(t('detail.elev'))}</div>
        <div class="dg-val" title="${escapeHTML(t('detail.elevTip'))}">${elevStr}</div></div>
      ${item(t('detail.flow'), escapeHTML(tv('flow.', s.flow)))}
      ${item(t('detail.wq'), `<div class="wq-list">${wqHTML}</div>`, ' style="grid-column:1/-1"')}
      ${item(t('detail.silting'), `<span style="color:${siltColor}">${escapeHTML(tv('val.', s.silting))}</span>`)}
      ${item(t('detail.lined'), escapeHTML(tv('val.', s.lined)))}
      ${item(t('detail.shape'), escapeHTML(tv('val.', s.shape)))}
      ${item(t('detail.dims'), escapeHTML(dimStr))}
    </div>
    <section class="detail-section" aria-labelledby="notes-h">
      <h3 class="detail-section-title" id="notes-h">${escapeHTML(t('detail.notes'))}</h3>
      ${s.notes
        ? `<div class="notes-text" lang="en">${escapeHTML(s.notes)}</div>${notesLang ? `<div class="no-notes">${escapeHTML(notesLang)}</div>` : ''}`
        : `<div class="no-notes">${escapeHTML(t('detail.noNotes'))}</div>`}
    </section>
    <section class="detail-section" aria-labelledby="photos-h">
      <h3 class="detail-section-title" id="photos-h">${escapeHTML(t('detail.photos', { n: digits(s.photos ? s.photos.length : 0) }))}</h3>
      <div class="photo-grid">${photosHTML}</div>
    </section>
  `;
  bindDetailActions();
}

function renderPOIDetail(poi) {
  const cat = tv('poi.', poi.cat);
  const title = `${cat} · #${digits(poi.fid)}`;
  const photosHTML = (poi.photos && poi.photos.length)
    ? poi.photos.map((p, i) => photoThumbHTML(p, t('detail.photo', { title, i: digits(i + 1) }))).join('')
    : `<div class="no-notes">${escapeHTML(t('poi.noPhotos'))}</div>`;
  const ch = chainageOfPoint(poi.lon, poi.lat);
  document.getElementById('detail-content').innerHTML = `
    <button class="detail-back" type="button" data-go-tab="map">${escapeHTML(t('detail.back'))}</button>
    <header class="detail-hero">
      <h2 class="detail-tole"><span aria-hidden="true">${poi.icon}</span> ${escapeHTML(cat)}</h2>
      <div class="detail-meta">${escapeHTML(t('poi.title', { n: digits(poi.fid) }))}${ch != null ? ` · ${escapeHTML(t('detail.station'))} ≈ ${formatStation(ch)}` : ''}</div>
    </header>
    <div class="dg-grid">
      <div class="dg-item" style="grid-column:1/-1">
        <div class="dg-label">${escapeHTML(t('poi.obs'))}</div>
        <div class="dg-val" lang="en">${escapeHTML(poi.comment || '—')}</div>
      </div>
      <div class="dg-item">
        <div class="dg-label">${escapeHTML(t('poi.lat'))}</div>
        <div class="dg-val mono">${N(poi.lat, 5)}°N</div>
      </div>
      <div class="dg-item">
        <div class="dg-label">${escapeHTML(t('poi.lon'))}</div>
        <div class="dg-val mono">${N(poi.lon, 5)}°E</div>
      </div>
    </div>
    <section class="detail-section" aria-labelledby="poi-photos-h">
      <h3 class="detail-section-title" id="poi-photos-h">${escapeHTML(t('detail.photos', { n: digits(poi.photos ? poi.photos.length : 0) }))}</h3>
      <div class="photo-grid">${photosHTML}</div>
    </section>
  `;
  bindDetailActions();
}

function bindDetailActions() {
  const root = document.getElementById('detail-content');
  root.querySelectorAll('[data-go-tab]').forEach(b => {
    b.addEventListener('click', () => showTab(b.dataset.goTab));
  });
  root.querySelectorAll('[data-go-section]').forEach(b => {
    b.addEventListener('click', () => {
      const s = CANAL_SECTIONS.find(x => x.pdf_n === +b.dataset.goSection);
      if (s) selectSection(s);
    });
  });
  root.querySelectorAll('.photo-thumb').forEach(btn => {
    btn.addEventListener('click', () => openLightbox(btn.dataset.full, btn.dataset.caption, btn.dataset.thumb, btn));
    const img = btn.querySelector('img');
    if (img) img.addEventListener('error', () => {
      btn.innerHTML = `<div class="photo-placeholder"><span>📷</span><div>${escapeHTML(t('photo.unavailable'))}</div></div>`;
    }, { once: true });
  });
}

function photoThumbHTML(filename, caption) {
  const safe = escapeHTML(filename);
  const cap  = escapeHTML(caption);
  return `<button class="photo-thumb" type="button" data-full="${PHOTO_FULL_BASE}${safe}" data-thumb="${PHOTO_THUMB_BASE}${safe}" data-caption="${cap}" aria-label="${cap}">
    <img src="${PHOTO_THUMB_BASE}${safe}" alt="${cap}" loading="lazy" width="400" height="300">
  </button>`;
}

// ── LIGHTBOX ────────────────────────────────────────────────
let lightboxReturnFocus = null;
function openLightbox(src, caption, fallbackSrc, opener) {
  let lb = document.getElementById('lightbox');
  if (!lb) {
    lb = document.createElement('div');
    lb.id = 'lightbox';
    lb.setAttribute('role', 'dialog');
    lb.setAttribute('aria-modal', 'true');
    lb.innerHTML = `<button class="lb-close" type="button">✕</button>
                    <img alt=""><div class="lb-caption"></div>`;
    document.body.appendChild(lb);
    lb.querySelector('.lb-close').addEventListener('click', closeLightbox);
    lb.addEventListener('click', e => { if (e.target === lb) closeLightbox(); });
  }
  lb.querySelector('.lb-close').setAttribute('aria-label', t('lightbox.close'));
  const img = lb.querySelector('img');
  // If the 800 px copy is missing, fall back to the gallery thumbnail.
  img.onerror = fallbackSrc ? () => { img.onerror = null; img.src = fallbackSrc; } : null;
  img.src = src;
  img.alt = caption || '';
  lb.querySelector('.lb-caption').textContent = caption || '';
  lb.classList.add('open');
  document.body.style.overflow = 'hidden';
  lightboxReturnFocus = opener || document.activeElement;
  lb.querySelector('.lb-close').focus();
}
function closeLightbox() {
  const lb = document.getElementById('lightbox');
  if (lb) { lb.classList.remove('open'); document.body.style.overflow = ''; }
  if (lightboxReturnFocus && lightboxReturnFocus.focus) lightboxReturnFocus.focus();
  lightboxReturnFocus = null;
}

// ── TAB NAVIGATION ──────────────────────────────────────────
function bindNavTabs() {
  document.querySelectorAll('.nav-tab').forEach(tab => {
    tab.addEventListener('click', () => showTab(tab.dataset.tab));
  });
}

function showTab(name) {
  document.querySelectorAll('.panel').forEach(p => p.classList.remove('active'));
  document.getElementById('panel-' + name).classList.add('active');
  document.querySelectorAll('.nav-tab').forEach(tab => {
    const active = tab.dataset.tab === name;
    tab.classList.toggle('active', active);
    tab.setAttribute('aria-selected', active);
  });
  if (name === 'map' && map) {
    sectionLayers.forEach(({ line }) => line.setStyle({ weight: 5, opacity: 0.9 }));
    activeSection = null;
  }
}

// "Download the survey data" links anywhere on the page open the Analysis tab's download list.
function bindDownloadLinks() {
  document.addEventListener('click', e => {
    const link = e.target.closest('[data-go-downloads]');
    if (!link) return;
    e.preventDefault();
    showTab('analysis');
    expandMobileSheet();
    document.getElementById('downloads')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  });
}

// Show the size of the zip next to its link (works on any web server, not file://).
function fillDownloadSizes() {
  if (!/^https?:/.test(location.protocol)) return;
  document.querySelectorAll('[data-dl-size]').forEach(el => {
    fetch(el.dataset.dlSize, { method: 'HEAD' }).then(r => {
      const bytes = +r.headers.get('content-length');
      if (r.ok && bytes) { el.dataset.bytes = bytes; renderDownloadSizes(); }
    }).catch(() => {});
  });
}
function renderDownloadSizes() {
  document.querySelectorAll('[data-dl-size][data-bytes]').forEach(el => {
    el.textContent = `(${N(+el.dataset.bytes / 1024)} KB)`;
  });
}

// ── SEARCH ──────────────────────────────────────────────────
function bindSearch() {
  const inp = document.getElementById('search');
  const res = document.getElementById('search-results');
  if (!inp || !res) return;
  let selIdx = -1;
  function update(query) {
    const q = (query || '').trim().toLowerCase();
    if (!q) { res.classList.remove('open'); res.innerHTML = ''; selIdx = -1; return; }
    const hits = [];
    CANAL_SECTIONS.forEach(s => {
      const tole = (s.tole || '').toLowerCase();
      const pdfStr = String(s.pdf_n || '');
      const fidStr = String(s.mergin_fid || '');
      if (pdfStr === q || tole.includes(q) || fidStr === q) hits.push({ kind: 'section', s });
    });
    CANAL_POIS.forEach(p => {
      const c = (p.comment || '').toLowerCase();
      const cat = (p.cat || '').toLowerCase();
      const catLocal = tv('poi.', p.cat).toLowerCase();
      if (String(p.fid) === q || c.includes(q) || cat.includes(q) || catLocal.includes(q)) hits.push({ kind: 'poi', p });
    });
    const limited = hits.slice(0, 12);
    res.innerHTML = limited.map((h, i) => {
      if (h.kind === 'section') {
        const s = h.s;
        return `<button class="search-result" type="button" data-kind="section" data-id="${s.pdf_n}" aria-selected="${i===selIdx}">
          <span class="sr-tag">#${digits(s.pdf_n)}</span> ${escapeHTML(s.tole || '—')}
          <span class="sr-tag" style="margin-left:auto">${escapeHTML(t('cond.' + s.condition))}</span></button>`;
      }
      const p = h.p;
      return `<button class="search-result" type="button" data-kind="poi" data-id="${p.fid}" aria-selected="${i===selIdx}">
        <span class="sr-tag">#${digits(p.fid)}</span> ${escapeHTML(tv('poi.', p.cat))}
        <span class="sr-tag" style="margin-left:auto">${escapeHTML((p.comment || '').slice(0, 24))}</span></button>`;
    }).join('');
    res.classList.toggle('open', !!limited.length);
    res.querySelectorAll('.search-result').forEach(b => {
      b.addEventListener('click', () => {
        if (b.dataset.kind === 'section') {
          const s = CANAL_SECTIONS.find(x => x.pdf_n === +b.dataset.id);
          if (s) selectSection(s);
        } else {
          const p = CANAL_POIS.find(x => x.fid === +b.dataset.id);
          if (p) selectPOI(p);
        }
        inp.value = ''; update('');
      });
    });
  }
  inp.addEventListener('input', () => update(inp.value));
  inp.addEventListener('focus', () => update(inp.value));
  inp.addEventListener('keydown', e => {
    const items = res.querySelectorAll('.search-result');
    if (e.key === 'ArrowDown') { e.preventDefault(); selIdx = Math.min(selIdx + 1, items.length - 1); items.forEach((b, i) => b.setAttribute('aria-selected', i === selIdx)); items[selIdx]?.scrollIntoView({ block: 'nearest' }); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); selIdx = Math.max(selIdx - 1, 0); items.forEach((b, i) => b.setAttribute('aria-selected', i === selIdx)); }
    else if (e.key === 'Enter') { e.preventDefault(); if (items[selIdx]) items[selIdx].click(); }
    else if (e.key === 'Escape') { inp.value = ''; update(''); inp.blur(); }
  });
  document.addEventListener('click', e => {
    if (!e.target.closest('.search-wrap')) res.classList.remove('open');
  });
}

// ── INDEX (sortable section list) ───────────────────────────
function buildIndex() {
  document.querySelectorAll('[data-sort]').forEach(b => {
    b.addEventListener('click', () => {
      const k = b.dataset.sort;
      if (indexSortKey === k) indexSortAsc = !indexSortAsc;
      else { indexSortKey = k; indexSortAsc = true; }
      document.querySelectorAll('[data-sort]').forEach(x =>
        x.setAttribute('aria-pressed', x.dataset.sort === indexSortKey));
      renderIndex();
    });
  });
  renderIndex();
}

function renderIndex() {
  const wrap = document.getElementById('index-list');
  if (!wrap) return;
  const list = CANAL_SECTIONS.filter(s => s.coords && s.coords.length >= 2).slice();
  list.sort((a, b) => {
    let va = a[indexSortKey], vb = b[indexSortKey];
    if (indexSortKey === 'condition') {
      va = CONDITIONS.indexOf(a.condition); vb = CONDITIONS.indexOf(b.condition);
      if (va < 0) va = 99; if (vb < 0) vb = 99;
    }
    if (va == null) va = Infinity; if (vb == null) vb = Infinity;
    return (va > vb ? 1 : va < vb ? -1 : 0) * (indexSortAsc ? 1 : -1);
  });
  wrap.innerHTML = list.map(s => {
    const cond = t('cond.' + s.condition);
    const sewage = hasSewage(s) ? ` · ${t('index.sewage')}` : '';
    return `<button class="index-row" type="button" data-go-section="${s.pdf_n}" aria-label="${escapeHTML(t('index.rowAria', { n: s.pdf_n, tole: s.tole || '', cond }))}">
      <span class="ix-chip" style="background:${s.color}"></span>
      <span><span class="ix-id">#${digits(s.pdf_n)}</span> <span class="ix-tole">${escapeHTML(s.tole || '—')}</span></span>
      <span class="ix-meta">${formatStation(s.chainage)} · ${escapeHTML(cond)}${escapeHTML(sewage)}</span>
    </button>`;
  }).join('');
  wrap.querySelectorAll('[data-go-section]').forEach(b => {
    b.addEventListener('click', () => {
      const s = CANAL_SECTIONS.find(x => x.pdf_n === +b.dataset.goSection);
      if (s) selectSection(s);
    });
  });
}

// ── ACCORDIONS ──────────────────────────────────────────────
function bindAccordions() {
  document.querySelectorAll('.acc').forEach(acc => {
    const head = acc.querySelector('.acc-head');
    if (!head) return;
    head.addEventListener('click', () => {
      const open = acc.getAttribute('aria-expanded') !== 'false';
      acc.setAttribute('aria-expanded', !open);
      head.setAttribute('aria-expanded', !open);
    });
  });
}

// ── KEYBOARD NAV ────────────────────────────────────────────
function bindKeyboard() {
  document.addEventListener('keydown', e => {
    if (e.target.matches('input, textarea')) return;
    if (e.key === 'Escape') {
      if (document.getElementById('lightbox')?.classList.contains('open')) {
        closeLightbox(); return;
      }
      if (tour.active) { exitTour(); return; }
    }
    if (e.key === '/' && !e.metaKey && !e.ctrlKey) {
      e.preventDefault();
      document.getElementById('search')?.focus();
    }
    if (!activeSection) return;
    const withGeom = CANAL_SECTIONS.filter(x => x.coords && x.coords.length >= 2);
    const i = withGeom.indexOf(activeSection);
    if (e.key === '[' || e.key === 'ArrowLeft') {
      if (i > 0) { e.preventDefault(); selectSection(withGeom[i - 1]); }
    } else if (e.key === ']' || e.key === 'ArrowRight') {
      if (i >= 0 && i < withGeom.length - 1) { e.preventDefault(); selectSection(withGeom[i + 1]); }
    }
  });
}

// ── URL DEEP LINKING ────────────────────────────────────────
function parseHash() {
  const out = {};
  (location.hash.replace(/^#/, '').split('&').filter(Boolean)).forEach(p => {
    const [k, v] = p.split('=');
    if (k) out[decodeURIComponent(k)] = v ? decodeURIComponent(v) : '';
  });
  return out;
}
function setHash(obj) {
  const parts = Object.entries(obj).filter(([k, v]) => v != null && v !== '')
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`);
  history.replaceState(null, '', '#' + parts.join('&'));
}
function applyHashOnLoad() {
  const h = parseHash();
  if (h.section != null && h.section !== '') {
    const s = CANAL_SECTIONS.find(x => String(x.pdf_n) === String(h.section));
    if (s) selectSection(s, { skipHash: true });
  } else if (h.poi != null && h.poi !== '') {
    const p = CANAL_POIS.find(x => String(x.fid) === String(h.poi));
    if (p) selectPOI(p, { skipHash: true });
  }
  if (h.tour === '1' && !tour.active) startTourMode();
}

// ── TOUR MODE ───────────────────────────────────────────────
// Titles and texts live in i18n.js (tour.N.t / tour.N.b); their numbers come from STATS.
const TOUR_STOPS = [
  { n: 1,  section: 1 },
  { n: 2,  section: 15 },
  { n: 3,  firstContamination: true },   // flies to the first Contamination point of interest
  { n: 4,  section: 53 },                // first section of the continuous sewage / waste reach
  { n: 5,  section: 67 },
  { n: 6,  section: 78 },
  { n: 7,  section: 88 },
  { n: 8,  section: 95, historic: true },
  { n: 9,  section: 107 },
  { n: 10, section: 1 },
];

function startTourMode() {
  tour.active = true;
  tour.idx = 0;
  document.getElementById('tour').classList.add('open');
  renderTourStop();
  setHash({ tour: 1 });
}

function exitTour() {
  tour.active = false;
  document.getElementById('tour').classList.remove('open');
  setHash({});
  applyFilters();
}

function bindTourControls() {
  document.getElementById('tour-prev')?.addEventListener('click', () => { if (tour.idx > 0) { tour.idx--; renderTourStop(); } });
  document.getElementById('tour-next')?.addEventListener('click', () => {
    if (tour.idx < TOUR_STOPS.length - 1) { tour.idx++; renderTourStop(); }
    else exitTour();
  });
  document.getElementById('tour-close')?.addEventListener('click', exitTour);
  document.getElementById('tour-skip')?.addEventListener('click', exitTour);
}

function renderTourStop({ fly = true } = {}) {
  const stop = TOUR_STOPS[tour.idx];
  if (!stop) return;
  const P = statParams();
  document.getElementById('tour-num').textContent = t('tour.stop', { i: digits(tour.idx + 1), n: digits(TOUR_STOPS.length) });
  document.getElementById('tour-title').textContent = t(`tour.${stop.n}.t`, P);
  document.getElementById('tour-body').innerHTML = t(`tour.${stop.n}.b`, P);
  const prog = document.getElementById('tour-progress');
  if (prog) {
    prog.innerHTML = TOUR_STOPS.map((_, i) =>
      `<span class="${i < tour.idx ? 'done' : i === tour.idx ? 'active' : ''}"></span>`
    ).join('');
  }
  document.getElementById('tour-next').textContent =
    (tour.idx === TOUR_STOPS.length - 1) ? t('tour.finish') : t('tour.next');
  if (!fly) return;

  if (stop.historic) {
    document.querySelector('.flt-feature[value="historic"]').checked = true;
    filterState.features.add('historic');
    applyFilters();
  }
  if (stop.firstContamination && STATS.contam[0]) {
    const p = STATS.contam[0].poi;
    map.flyTo([p.lat, p.lon], 17, { duration: 1.2 });
    return;
  }
  const s = CANAL_SECTIONS.find(x => x.pdf_n === stop.section && x.coords && x.coords.length);
  if (s) {
    const mid = s.coords[Math.floor(s.coords.length / 2)];
    map.flyTo([mid[1], mid[0]], 16, { duration: 1.2 });
  }
}

