// ── STUDY TAB: the report's main points and key diagrams ────
// Images are web-sized copies of the report figures (scripts/publish_report.py).
const STUDY_FIGS = [
  { id: '2_1',  kind: 'fig', num: '2.1',  src: 'figures/fig_2_1_system.png' },
  { id: '5_1',  kind: 'fig', num: '5.1',  src: 'figures/fig_5_1_flow.png' },
  { id: '6_1',  kind: 'fig', num: '6.1',  src: 'figures/fig_6_1_attributes.png' },
  { id: '4_1',  kind: 'fig', num: '4.1',  src: 'figures/fig_4_1_intake.jpg' },
  { id: '8_1',  kind: 'map', num: '8.1',  src: 'figures/map_8_1_priority.jpg' },
  { id: '9_1',  kind: 'fig', num: '9.1',  src: 'figures/fig_9_1_stakeholders.png' },
  { id: '10_1', kind: 'fig', num: '10.1', src: 'figures/fig_10_1_phasing.png' },
];
// Main points, in reading order, with the diagrams that show them.
const STUDY_POINTS = [
  { key: 'sp.system',   figs: ['2_1'] },
  { key: 'sp.flow',     figs: ['5_1'] },
  { key: 'sp.intake',   figs: ['4_1'] },
  { key: 'sp.hidden',   figs: ['6_1'] },
  { key: 'sp.priority', figs: ['8_1'] },
  { key: 'sp.plan',     figs: ['9_1', '10_1'] },
  { key: 'sp.unknown',  figs: [] },
];

function studyFigLabel(f) {
  return `${t(f.kind === 'map' ? 'study.map' : 'study.fig')} ${digits(f.num)}`;
}

function renderStudy() {
  const pointsEl = document.getElementById('study-points');
  const figsEl = document.getElementById('study-figures');
  if (!pointsEl || !figsEl) return;
  const P = statParams();
  const byId = Object.fromEntries(STUDY_FIGS.map(f => [f.id, f]));
  pointsEl.innerHTML = STUDY_POINTS.map(p => {
    const refs = p.figs.map(id => `<button class="study-figlink" type="button" data-study-fig="${id}">${escapeHTML(studyFigLabel(byId[id]))}</button>`).join(' ');
    return `<li><span class="study-point-text">${t(p.key, P)}</span>${refs ? ` <span class="study-refs">${refs}</span>` : ''}</li>`;
  }).join('');
  figsEl.innerHTML = STUDY_FIGS.map(f => {
    const title = t(`sf.${f.id}.title`, P), text = t(`sf.${f.id}.text`, P);
    return `<figure class="study-fig" id="study-fig-${f.id}">
      <button class="study-fig-img" type="button" data-study-fig="${f.id}" aria-label="${escapeHTML(studyFigLabel(f) + ' — ' + title)}">
        <img src="${f.src}" alt="${escapeHTML(title)}" loading="lazy">
      </button>
      <figcaption><span class="study-fig-num">${escapeHTML(studyFigLabel(f))}</span> <strong>${escapeHTML(title)}</strong><br>${text}</figcaption>
    </figure>`;
  }).join('');
}

function bindStudy() {
  document.addEventListener('click', e => {
    const btn = e.target.closest('[data-study-fig]');
    if (!btn) return;
    const f = STUDY_FIGS.find(x => x.id === btn.dataset.studyFig);
    if (!f) return;
    openLightbox(f.src, `${studyFigLabel(f)} — ${t(`sf.${f.id}.title`, statParams())}`, null, btn);
  });
}

// ── CONDITION STRIP (Analysis tab) ──────────────────────────
// A linear "ribbon" of the canal: every section drawn at its chainage, coloured by
// condition, with ticks where sewage / waste dumping was recorded.
function renderConditionStrip() {
  const wrap = document.getElementById('condition-strip');
  const summary = document.getElementById('condition-summary');
  if (!wrap) return;
  const secs = CANAL_SECTIONS.filter(s => s.chainage != null && s.sec_len != null);
  if (!secs.length) { wrap.innerHTML = `<div class="no-notes">${escapeHTML(t('strip.none'))}</div>`; return; }

  // The SVG is stretched to a fixed CSS height (preserveAspectRatio="none"), so it
  // only holds rectangles; the km axis is plain HTML so its text never distorts.
  const total = STATS.mainM;
  const W = 1000, BAR_H = 72, TICK_Y = 80, TICK_H = 20;
  const x = m => (m / total) * W;

  const blocks = secs.map(s => {
    const x0 = x(chainageStart(s)), w = Math.max(x(s.sec_len), 1.5);
    const tip = t('strip.tip', {
      label: sectionLabel(s), cond: t('cond.' + s.condition),
      from: formatStation(chainageStart(s)), to: formatStation(s.chainage),
    }) + (wqList(s).length ? `; ${wqList(s).map(w => tv('wq.', w)).join(' + ')}` : '');
    return `<rect class="cs-block${isPlaceholder(s) ? ' cs-placeholder' : ''}" x="${x0.toFixed(1)}" y="0" width="${w.toFixed(1)}" height="${BAR_H}"
              fill="${CONDITION_COLORS[s.condition] || s.color}" data-go-section="${s.pdf_n}" tabindex="0" role="button"
              aria-label="${escapeHTML(tip)}"><title>${escapeHTML(tip)}</title></rect>`;
  }).join('');

  const ticks = secs.filter(hasSewage).map(s => {
    const x0 = x(chainageStart(s)), w = Math.max(x(s.sec_len), 3);
    return `<rect class="cs-sewage" x="${x0.toFixed(1)}" y="${TICK_Y}" width="${w.toFixed(1)}" height="${TICK_H}"><title>${escapeHTML(t('strip.sewTip', { label: sectionLabel(s) }))}</title></rect>`;
  }).join('');

  const kmTicks = [];
  for (let k = 2; k * 1000 < total - 500; k += 2) {
    kmTicks.push(`<span style="left:${(100 * k * 1000 / total).toFixed(2)}%">${N(k)} ${escapeHTML(t('unit.km'))}</span>`);
  }

  wrap.innerHTML = `<svg viewBox="0 0 ${W} ${TICK_Y + TICK_H}" preserveAspectRatio="none" role="img"
      aria-label="${escapeHTML(t('strip.aria'))}">${blocks}${ticks}</svg>
    <div class="cs-axis">${kmTicks.join('')}</div>
    <div class="cs-ends"><span>${escapeHTML(t('strip.start'))}</span><span>${escapeHTML(t('strip.end', { km: km(total) }))}</span></div>`;

  wrap.querySelectorAll('[data-go-section]').forEach(el => {
    const go = () => {
      if (!map) return;
      const s = CANAL_SECTIONS.find(v => v.pdf_n === +el.dataset.goSection);
      if (s) selectSection(s);
    };
    el.addEventListener('click', go);
    el.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); go(); } });
  });

  if (summary) {
    // Lengths per condition (all sections, so parallel branches count too).
    const byCond = {};
    let sum = 0;
    secs.forEach(s => { byCond[s.condition] = (byCond[s.condition] || 0) + s.sec_len; sum += s.sec_len; });
    const rows = CONDITIONS.filter(c => byCond[c]).map(c =>
      `<div class="cs-row"><span class="ix-chip" style="background:${CONDITION_COLORS[c]}"></span>
         <span>${escapeHTML(t('cond.' + c))}</span><span class="cs-num">${km(byCond[c], 2)} ${escapeHTML(t('unit.km'))} · ${N(100 * byCond[c] / sum)}%</span></div>`
    ).join('');
    summary.innerHTML = `${rows}<p class="cs-note">${t('summary.note', {
      sewKm: km(STATS.sewM, 1), sewN: N(STATS.sewN), n: N(secs.length), sumKm: km(sum), mainKm: km(total),
    })}</p>`;
  }
}

// ── MOBILE BOTTOM SHEET ─────────────────────────────────────
function expandMobileSheet() {
  if (isMobile()) document.getElementById('sidebar')?.classList.add('expanded');
}

function bindMobileSheet() {
  const sidebar = document.getElementById('sidebar');
  const header  = sidebar.querySelector('.sidebar-header');
  if (!header) return;
  header.addEventListener('click', e => {
    if (window.innerWidth > 768) return;
    if (e.target.closest('button, a, input')) return;
    sidebar.classList.toggle('expanded');
  });
}

// ── UTILITIES ───────────────────────────────────────────────
function escapeHTML(s) {
  if (s == null) return '';
  return String(s).replace(/[&<>"']/g, c => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  }[c]));
}
